structureEvidence.animationCss:
@keyframes tiaobi { 
  0% { top: 0px; opacity: 0; }
  50% { top: -40px; transform: rotateY(-1turn); opacity: 1; }
  100% { top: 0px; transform: rotateY(0deg); opacity: 0; }
}
@keyframes num-tipdown { 
  33% { top: -3px; opacity: 1; }
  66% { top: -3px; opacity: 1; }
  100% { top: -3px; opacity: 0; }
}
@keyframes num { 
  100% { transform: translateY(10px); opacity: 0; }
}
@keyframes num-move { 
  100% { top: 3px; opacity: 1; }
}

